-- No ROM/GPU needed. Reference digests were generated by compiling SameBoy's
-- unmodified GB_convert_rgb15 at 26a56bd6a122a6318a456abd80558408742d5adf,
-- CGB_E, neutral temperature, RGB byte order, RGB555 values 0..32767.
package.path = "./?.lua;./?/init.lua;" .. package.path
local T = require("tests.harness")
local C = require("src.render.GbcColorCorrection")
local SaveData = require("src.core.SaveData")
local GenOptions = require("src.core.GenOptions")
local Version = require("src.core.GameVersion")
local Palette = require("src.render.PaletteFX")

T.eq(SaveData.defaultOptions().gbcColorCorrection, "off", "existing installations keep their colours")
T.eq(SaveData.mergeOptions({}).gbcColorCorrection, "off", "old options default to OFF")
T.eq(C.normalize("invalid"), "off", "unknown profile falls back to OFF")
T.eq(C.normalize(true), "off", "invalid option type falls back to OFF")
T.eq(C.cycle(nil, 1), "accurate", "first step selects Modern Accurate")
T.eq(C.cycle("accurate", 1), "harsh", "next step selects Harsh Reality")
T.eq(C.cycle("harsh", 1), "off", "forward wraps to OFF")
T.eq(C.cycle("off", -1), "harsh", "left cycles backwards")
local opts = { gbcColorCorrection = "invalid", untouched = true }
C.applyOptions(opts)
T.eq(C.mode, "off", "applyOptions sanitizes the live mode")
T.eq(opts.gbcColorCorrection, "invalid", "presentation never rewrites saved settings")
T.check(opts.untouched, "unrelated options survive")

local expected = { accurate = 37176544, harsh = 1187375320 }
for _, mode in ipairs({ "accurate", "harsh" }) do
  local hash, bounded = 0, true
  for b = 0, 31 do for g = 0, 31 do for r = 0, 31 do
    local nr, ng, nb = C.convert5(r, g, b, mode)
    for _, v in ipairs({ nr, ng, nb }) do
      bounded = bounded and v >= 0 and v <= 255 and v == math.floor(v)
      hash = (hash * 33 + v) % 4294967296
    end
  end end end
  T.eq(hash, expected[mode], mode .. " matches all 32768 upstream RGB555 colours")
  T.check(bounded, mode .. " always returns valid integer RGB888")
end
T.same({ C.convert5(0, 0, 0, "accurate") }, { 0, 0, 0 }, "accurate keeps black")
T.same({ C.convert5(31, 31, 31, "accurate") }, { 255, 255, 255 }, "accurate keeps white")
T.same({ C.convert5(0, 0, 0, "harsh") }, { 45, 41, 38 }, "LCD profile has the upstream black point")
T.same({ C.convert5(31, 31, 31, "harsh") }, { 161, 166, 156 }, "LCD profile has the upstream white point")
T.same({ C.convert5(31, 0, 16, "off") }, { 255, 0, 132 }, "OFF reference uses uncorrected RGB555 expansion")

local wire = SaveData.encode({ gbcColorCorrection = "harsh", speed = 2 })
T.eq(SaveData.decode(wire).gbcColorCorrection, "harsh", "selection survives serialization")
local scoped = { gbcColorCorrection = "off", perGeneration = { [2] = { gbcColorCorrection = "accurate" } } }
T.eq(GenOptions.resolve(scoped, 1).gbcColorCorrection, "off", "Gen 1 keeps its shared value")
T.eq(GenOptions.resolve(scoped, 2).gbcColorCorrection, "accurate", "Gen 2 can override its correction")
T.eq(GenOptions.resolve(scoped, 3).gbcColorCorrection, "off", "Gen 3 keeps its shared value")

_G.love = require("tests.love_stub")
local Options = require("src.ui.OptionsMenu")
local function rowFor(version)
  Version.set(version)
  local game = { save = { options = SaveData.defaultOptions() }, data = {} }
  for _, row in ipairs(Options.buildRows(game)) do
    if row.id == "gbcColorCorrection" then return row, game end
  end
end
T.eq(rowFor("red"), nil, "correction is not offered on Gen 1")
T.eq(rowFor("emerald"), nil, "correction is not offered on Gen 3")
local row, game = rowFor("gold")
T.check(row ~= nil, "Gold offers the correction row")
T.eq(row.value(game), "OFF", "in-game row initially shows OFF")
row.step(game, 1)
T.eq(game.save.options.gbcColorCorrection, "accurate", "in-game row stores the selected profile")
T.eq(C.mode, "accurate", "in-game row applies live")
row.step(game, -1)
T.eq(C.mode, "off", "in-game left restores OFF")
local writes = 0
game.input = { wasPressed = function(_, key) return key == "right" end }
game.writeOptions = function() writes = writes + 1 end
local menu = Options.new(game)
for i, entry in ipairs(menu.rows) do
  if entry.id == "gbcColorCorrection" then menu.index = i end
end
menu:update(1 / 60)
T.eq(C.mode, "accurate", "mapped menu input changes the live profile")
T.eq(writes, 1, "mapped menu input persists through the normal options writer")
T.check(rowFor("silver") ~= nil, "Silver offers the correction row")
T.check(rowFor("crystal") ~= nil, "Crystal offers the correction row")
local RI = require("src.import.RomImporter")
local defaults
for _, entry in ipairs(RI.SETTINGS_ROWS) do
  if entry.id == "gbcColorCorrection" then defaults = entry end
end
T.same(defaults.values, { "off", "accurate", "harsh" }, "launcher offers the same profiles")

-- No GPU use at all on OFF, other generations or intentionally mono modes.
local allocations = 0
love.graphics.newShader = function() allocations = allocations + 1; error("no shaders") end
Version.set("gold")
Palette.setMode("gbc")
C.setMode("off")
local input = {}
T.eq(C.apply(input), input, "OFF returns the original surface")
C.setMode("accurate")
Version.set("red")
T.eq(C.apply(input), input, "other games return the original surface")
Version.set("gold")
Palette.setMode("classic")
T.eq(C.apply(input), input, "mono palettes return the original surface")
T.eq(allocations, 0, "inert paths allocate no shaders or canvases")
Palette.setMode("gbc")
T.eq(C.apply(input), input, "shader compilation failure preserves the frame")
T.eq(C.apply(input), input, "unsupported GPU remains a safe pass-through")
T.eq(allocations, 1, "unsupported shader is not retried each frame")
C.setMode("off")
Version.set("red")
T.finish("GBC colour correction")
